    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    line_rows = [r for r, row in enumerate(grid)
                 if row[0] != bg and all(v == row[0] for v in row)]
    if not line_rows:
        return [row[:] for row in grid]
    sep_colors = {grid[r][0] for r in line_rows}
    # Treat the full-width non-background stripes as separators, not as drawable content.
    out = [row[:] for row in grid]
    if len(line_rows) >= 2:
        # Repeated bands have a fixed vertical period. Copy visible marks to matching
        # positions in each period, leaving the separator stripes intact.
        diffs = [line_rows[i + 1] - line_rows[i] for i in range(len(line_rows) - 1)]
        import math
        period = diffs[0]
        for d in diffs[1:]:
            period = math.gcd(period, d)
        if period <= 0:
            return out
        for r in range(h):
            if grid[r][0] in sep_colors and all(v == grid[r][0] for v in grid[r]):
                continue
            for c in range(w):
                v = grid[r][c]
                if v == bg or v in sep_colors:
                    continue
                for rr in range(r % period, h, period):
                    if rr != r and not (grid[rr][0] in sep_colors and all(x == grid[rr][0] for x in grid[rr])):
                        out[rr][c] = v
        return out

    # One separator divides two panels. If their dimensions match, copy the
    # non-background marks from the populated panel into its counterpart.
    r = line_rows[0]
    top_h, bottom_h = r, h - r - 1
    if top_h == bottom_h:
        top_pop = sum(grid[i][j] != bg for i in range(r) for j in range(w))
        bot_pop = sum(grid[i][j] != bg for i in range(r + 1, h) for j in range(w))
        if top_pop >= bot_pop:
            src, dst = 0, r + 1
        else:
            src, dst = r + 1, 0
        for dr in range(top_h):
            for c in range(w):
                v = grid[src + dr][c]
                if v != bg:
                    out[dst + dr][c] = v
    return out
